DROP VIEW IF EXISTS reports.vwclaimrequest;
CREATE VIEW reports.vwclaimrequest AS SELECT cr.id, cr.patient_id, cr.encounter_id, cr.financial_document_id, cr.pre_authorization_id, cr.patient_insurance_id, cr.upload_name, cr.upload_id, cr.prov_claim_no, cr.claim_reference, cr.pre_auth_ref_no, cr.approval_response_id, cr.total_net, cr.status, cr.outcome, cr.message, cr.request_json, cr.response_json, cr.submitted_at, cr.created_by, cr.created_date, cr.last_modified_by, cr.last_modified_date, cr.validation_errors_json, cr.claim_type, cr.claim_sub_type FROM public.claim_request cr;
GRANT SELECT ON reports.vwclaimrequest TO report_user;
